// BuzzFYL UI wired to the real core (src/core/, src/brain.ts). The UI owns look, copy, flow and
// the clock; the core owns the simulation, the brain lookups, the settings and the economy.
// Nothing here computes a neural response or a game outcome: it reads core state and records.
import { Brain } from "../../src/brain";
import { loadNotebook, restoreBuild, saveAttempt } from "../../src/core/campaign";
import { decisiveEvents, firstDivergence, frozenTwin, replay, runPair } from "../../src/core/compare";
import { ARENA, baselineLevels, buildCost, CTRL, GAME, POLICY_COST, POLICY_THRESHOLD, SUGAR_COST, SWARM_LIMIT, SWARM_SIZES, swarmSize } from "../../src/core/config";
import { score } from "../../src/core/score";
import { Sim } from "../../src/core/sim";
import { LEVELS, WAVES } from "../../src/core/waves";

const $=s=>document.querySelector(s);const clone=x=>JSON.parse(JSON.stringify(x));
const fly=`<svg viewBox="0 0 64 64" fill="none" aria-hidden="true"><ellipse cx="23" cy="23" rx="11" ry="17" transform="rotate(-35 23 23)" fill="#e2eef0" stroke="#352d24" stroke-width="2"/><ellipse cx="42" cy="23" rx="11" ry="17" transform="rotate(35 42 23)" fill="#e2eef0" stroke="#352d24" stroke-width="2"/><ellipse cx="32" cy="39" rx="10" ry="18" fill="#51483c" stroke="#352d24" stroke-width="2"/><path d="M23 35h18M23 43h18M25 51h14M23 35l-10 8M41 35l10 8" stroke="#c3b494" stroke-width="2"/><circle cx="32" cy="22" r="10" fill="#51483c"/><circle cx="26" cy="20" r="5" fill="#b64032"/><circle cx="38" cy="20" r="5" fill="#b64032"/></svg>`;
const icons={water:'<path d="M12 3C10 7 5 12 5 16a7 7 0 0014 0c0-4-5-9-7-13z"/>',sugar:'<path d="M6 8l6-4 6 4v9l-6 4-6-4zM6 8l6 4 6-4M12 12v9"/>',bitter:'<path d="M5 19C3 7 12 3 20 4c1 11-5 17-13 15M6 19L17 7"/>',threat:'<path d="M12 3L2 21h20L12 3zM12 9v5M12 17v1"/>',learn:'<path d="M5 8a8 8 0 0114 0M19 3v5h-5M19 16a8 8 0 01-14 0M5 21v-5h5"/>',swarm:'<circle cx="7" cy="8" r="2.6"/><circle cx="17" cy="8" r="2.6"/><circle cx="12" cy="17" r="2.6"/>'};const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${icons[k]}</svg>`;

// ---- core-defined settings and economy ---------------------------------------------------
$('#app').innerHTML='<div class="shell"><p class="notice" style="padding:40px">Loading the measured brain export…</p></div>';
let brain;
try{brain=await Brain.load()}catch(e){$('#app').innerHTML=`<div class="shell"><p class="notice" style="padding:40px">Brain data unavailable: ${e.message}. Nothing is simulated without it.</p></div>`;throw e}
const lvl=()=>WAVES[st.level];
const scales={bitter:brain.levels.bitterScale,loomGf:brain.levels.loomGfScale};
const sugars=Object.keys(SUGAR_COST).map(Number);
const base0=baselineLevels(scales);
// Scout / reset: the unmodified connectome, weakest sugar input, slow learning. Costs nothing.
const defaults={sugarHz:sugars[0],bitterLevel:base0.bitter,loomGfLevel:base0.loomGf,policy:{bitter:'conservative',loomGf:'conservative'},swarm:0};
const query=new URLSearchParams(location.search);
const seed=Number(query.get('seed')??7);
const nSeeds=Math.max(...Object.values(brain.data.conditions).map(c=>c.runs.length));
const groupN=k=>brain.data.groups[k]?.root_ids.length??0;
const gname={bitter:'Bitter-cell outputs',loomGf:'Looming → Giant Fibre'};
const glow={bitter:'bitter-cell outputs',loomGf:'looming → Giant Fibre'};
// UI setting key -> BuildConfig field
const field={bitter:'bitterLevel',threat:'loomGfLevel'},grp={bitter:'bitter',threat:'loomGf'};
const level=(c,k)=>k==='swarm'?c.swarm??0:c[field[k]];
const setLevel=(c,k,v)=>{if(k==='swarm')c.swarm=v;else c[field[k]]=v};
const levelText=(c,k)=>k==='swarm'?(swarmSize(c)===1?'1 fly':swarmSize(c)+' flies'):k==='sugar'?`${c.sugarHz} Hz`:`×${scales[grp[k]][c[field[k]]]}`;
const stateOf=c=>({bitterScale:scales.bitter[c.bitterLevel],loomGfScale:scales.loomGf[c.loomGfLevel]});
const measured=c=>brain.stateAvailable(stateOf(c),true);
const cost=()=>buildCost(st.config,defaults);
const budget=()=>lvl().budget;
const canRelease=()=>cost()<=budget()&&measured(st.config)&&!st.live;
const brainLine=c=>`${swarmSize(c)===1?'1 fly':swarmSize(c)+' flies'}, sugar ${c.sugarHz} Hz, bitter ×${scales.bitter[c.bitterLevel]}, threat ×${scales.loomGf[c.loomGfLevel]}`;

// Scout: the unmodified brain in the smallest swarm that can clear a level.
const scout={...defaults,policy:{...defaults.policy},swarm:1};
let saved=loadNotebook().filter(a=>LEVELS.includes(a?.record?.wave)&&typeof a.record.metrics?.flies==='number');
let st={level:LEVELS.includes(query.get('level'))?query.get('level'):LEVELS[0],view:'picnic',selected:'bitter',config:clone(defaults),runs:saved,chosen:saved.at(-1)?.id,live:null,notice:'',speed:1,paused:false,replay:0,compare:null};
const meta={swarm:{title:'Swarm',desc:'Choose how many flies you release.',detail:`Every fly has the same brain, and the swarm shares one set of weights: what happens to any fly trains all of them. More flies means spare bodies and faster learning, but they share the food on the lawn and every fly lost costs score. One fly is free and each point doubles the swarm: 2, 4, 8, 16. A level needs two flies across, so a lone fly cannot clear it. ${SWARM_LIMIT} flies is the limit, and a full swarm of ${SWARM_LIMIT} cannot win.`,group:'Swarm size and shared weights are game rules, not measurements'},water:{title:'Water',desc:'Hydration is part of the picnic, not a setting.',detail:`Water taste cells (${groupN('water')} neurons) were run in the model. On their own they drive the feeding motor neuron MN9 only weakly, about 20 Hz, so drinking is slow. The ${CTRL.drinkMn9Hz} Hz drink threshold is ours. Droplets and soda spills appear at the picnic; there is no slider and no point cost.`,group:`Water taste cells · ${groupN('water')} neurons`},sugar:{title:'Sugar',desc:'Set how strongly food stimulates sugar-sensing cells.',detail:'Sugar is a sensory input: increasing this level sends stronger stimulation into sugar-sensing cells.',group:`LB3c sugar cells · ${groupN('sugar')} neurons`},bitter:{title:'Bitter',desc:'Set the starting strength of bitter-cell outputs.',detail:'Bitter cells signal a reason to reject food. This setting scales their outgoing connections, so weakening it can allow feeding despite a bitter taste. Safe meals weaken this group; poisoning strengthens it under the selected learning policy.',group:`Bitter-cell outgoing connections · ${groupN('bitter')} neurons`},threat:{title:'Threat',desc:'Set the starting strength of looming-to-escape connections.',detail:'An approaching shape supplies looming input. This setting scales the direct connections into Giant Fibre, the escape output. Stronger connections favor escape but can interrupt meals. Other threat pathways may still suppress feeding even when these direct connections are weak.',group:`LC4 / LPLC2 → Giant Fibre · ${groupN('looming')} → ${groupN('giant_fibre')} neurons`},learn:{title:'Learning',desc:'Decide how readily experience changes each connection group.',detail:`Responsive updates after ${POLICY_THRESHOLD.responsive} qualifying event. Conservative collects ${POLICY_THRESHOLD.conservative}. These are authored learning rules applied to real connectivity.`,group:'Bitter and threat connection groups'}};
const outcomes={survived:'Two or more flies across and laying',not_crossed:'Fewer than two flies across and laying',wiped_out:'Whole swarm lost',died_health:'Died from damage',died_energy:'Died: ran out of energy',died_thirst:'Died of thirst',running:'Ended early'};
const actions={idle:'Looking around',walking:'Walking (authored)',feeding:'Feeding (MN9)',drinking:'Drinking (MN9)',suppressed:'Feeding suppressed, no jump',refusing:'Refusing food (MN9 low)',escaping:'Escape jump (Giant Fibre)',laying:'Laying eggs on the fruit'};
const pct=x=>Math.round(x*100)+'%';const hz=x=>Math.round(x)+' Hz';
function toast(t){document.querySelector('.toast')?.remove();let e=document.createElement('div');e.className='toast';e.role='status';e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),4000)}
function nav(v){stopReplay();if(st.live&&st.view==='live'){st.paused=true}st.view=v;render()}
const number=a=>st.runs.findIndex(x=>x.id===a.id)+1;
const chosen=()=>st.runs.find(x=>x.id===st.chosen)||st.runs.at(-1);
const beaten=l=>st.runs.some(a=>a.record.wave===l&&a.record.result==='survived');
const title=w=>WAVES[w].title.replace('—','·');
const outcome=r=>r.result==='not_crossed'&&r.metrics.flies>=SWARM_LIMIT&&r.metrics.fliesAcross>=2?`A full swarm of ${SWARM_LIMIT} cannot win`:r.metrics.flies<2&&r.result!=='running'?(r.metrics.fliesAcross?'One fly made it, but a level needs two':'A lone fly cannot clear a level'):outcomes[r.result];
const flyWord=n=>n===1?'1 fly':n+' flies';

// ---- brain monitor: schematic layout, measured rates only --------------------------------
const bar=(label,v,thr,max=220)=>`<div class="mrow"><span>${label}</span><div class="mbar"><i class="${thr!=null&&v>=thr?'hit':''}" style="width:${Math.min(100,v/max*100)}%"></i>${thr!=null?`<em style="left:${thr/max*100}%" title="threshold ${thr} Hz (authored)"></em>`:''}</div><b>${hz(v)}</b></div>`;
// Schematic map of the model's named cell groups. Node brightness = input rate or measured output rate
// of one looked-up model run; nothing here is anatomy and nothing is animated from invented data.
function brainMap(d,bs,sel){
  const i=d?{sugar:d.stimulus.sugar,bitter:d.stimulus.bitter,water:d.stimulus.water??0,looming:d.stimulus.looming}:{sugar:0,bitter:0,water:0,looming:0};
  const o=d?{mn9:d.readouts.mn9,gf:d.readouts.giant_fibre,mdn:d.readouts.mdn}:{mn9:0,gf:0,mdn:0};
  const a=(v,m)=>Math.min(1,v/m),A={sugar:a(i.sugar,200),bitter:a(i.bitter,200),water:a(i.water,400),looming:a(i.looming,100),mn9:a(o.mn9,100),gf:a(o.gf,200),mdn:a(o.mdn,100)};
  const P={sugar:[36,24],bitter:[36,62],water:[36,100],looming:[36,140],mn9:[250,40],gf:[250,100],mdn:[250,146]};
  const edge=(f,t,inh,w)=>{const[x1,y1]=P[f],[x2,y2]=P[t],on=A[f]>0;return `<path d="M${x1} ${y1} C 120 ${y1}, 170 ${y2}, ${x2} ${y2}" fill="none" stroke="${on?(inh?'#7a4fb0':'#c9768c'):'#b8c5be'}" stroke-width="${on?1.5+2.5*A[f]:1}" ${inh?'stroke-dasharray="4 3"':''} class="${on?'flow':''}"/>${w?`<text x="${(x1+x2)/2-4}" y="${(y1+y2)/2+(inh?-4:12)}" class="w">${w}</text>`:''}`};
  const node=(k,label,n,val,key)=>{const[x,y]=P[k],r=5+Math.sqrt(n)/1.6,left=x<140;return `<circle cx="${x}" cy="${y}" r="${Math.min(15,r)}" fill="#435b70" fill-opacity="${.12+.88*A[k]}" stroke="${sel===key?'#c9768c':'#435b70'}" stroke-width="${sel===key?3:1.2}" class="${A[k]>0?'fire':''}"/><text x="${left?x+18:x+12}" y="${left?y-3:y-13}" text-anchor="${left?'start':'end'}">${label}</text><text x="${left?x+18:x+12}" y="${left?y+9:y+21}" text-anchor="${left?'start':'end'}" class="v">${val}</text>`};
  return `<svg class="brainmap" viewBox="0 0 286 166" role="img" aria-label="Schematic of the model's sensory groups and motor outputs with their current rates"><ellipse cx="143" cy="84" rx="54" ry="60" fill="#c9768c" fill-opacity="${d?.06+Math.min(.3,d.neuronsActive/20000):.05}" stroke="#b8c5be"/><text x="143" y="80" text-anchor="middle" class="v">${d?d.neuronsActive.toLocaleString():'whole-brain'}</text><text x="143" y="92" text-anchor="middle" class="v">${d?'neurons fired':'model'}</text>${edge('sugar','mn9')}${edge('water','mn9')}${edge('bitter','mn9',true,'×'+bs.bitterScale)}${edge('looming','gf',false,'×'+bs.loomGfScale)}${edge('looming','mn9',true)}${edge('looming','mdn')}${node('sugar','Sugar',groupN('sugar'),d?i.sugar+' Hz':groupN('sugar')+' cells','sugar')}${node('bitter','Bitter',groupN('bitter'),d?i.bitter+' Hz':groupN('bitter')+' cells','bitter')}${node('water','Water',groupN('water'),d?i.water+' Hz':groupN('water')+' cells','water')}${node('looming','Looming',groupN('looming'),d?i.looming+' Hz':groupN('looming')+' cells','threat')}${node('mn9','MN9 feed',8,d?hz(o.mn9):'',null)}${node('gf','Giant Fibre',16,d?hz(o.gf):'jump',null)}${node('mdn','MDN',8,d?hz(o.mdn):'',null)}</svg>`}
function monitor(){
  const sim=st.view==='live'?st.live:null,c=sim?sim.config:st.config,sel=st.view==='workbench'?st.selected:null;
  const bs=sim?sim.brainState:stateOf(c),d=sim?.lastDecision;
  let h=brainMap(d,bs,sel==='learn'?'bitter':sel);
  if(sim){
    h+=`<h4>${d?`Fly ${d.flyId+1} · ${d.t.toFixed(1)} s`:'Waiting for input'}</h4>`;
    if(!d)h+='<p class="meta">No sensory input yet, so nothing has been looked up.</p>';
    else h+=bar('MN9 · feed',d.readouts.mn9,d.stimulus.water&&!d.stimulus.sugar?CTRL.drinkMn9Hz:CTRL.feedMn9Hz)+bar('Giant Fibre · jump',d.readouts.giant_fibre,CTRL.escapeGfHz)+`<p class="why">${d.reason}</p><p class="meta">${d.conditionId} · model seed ${d.replicateSeed}</p>`;
  }else if(measured(c)){
    const m=s=>brain.mean(bs,s);
    h+=`<h4>Measured for this build</h4>`+bar(`Sugar ${c.sugarHz}`,m({sugar:c.sugarHz,bitter:0,looming:0}).mn9,CTRL.feedMn9Hz)+bar('Sugar + bitter',m({sugar:c.sugarHz,bitter:200,looming:0}).mn9,CTRL.feedMn9Hz)+bar('Water alone',m({sugar:0,bitter:0,looming:0,water:400}).mn9,CTRL.drinkMn9Hz)+bar('Looming 30',m({sugar:0,bitter:0,looming:30}).giant_fibre,CTRL.escapeGfHz)+bar('Looming 50',m({sugar:0,bitter:0,looming:50}).giant_fibre,CTRL.escapeGfHz)+`<p class="meta">Top three: MN9 (feed). Bottom two: Giant Fibre (jump). Tick = our threshold.</p>`;
  }else h+='<p class="why">This brain state is not measured yet. It cannot be released.</p>';
  return h;
}
function updateMonitor(){const e=$('#monitor');if(e)e.innerHTML=monitor()}

function render(){let active=st.view==='live'||st.view==='results'||st.view==='compare'||st.view==='summary'?'picnic':st.view;$('#app').innerHTML=`<div class="shell"><header class="top"><div class="brand"><h1>BuzzFYL</h1><span>BUZZ FOR YOUR LIFE</span></div><nav class="nav" aria-label="Main navigation">${[['workbench','Workbench'],['picnic','Picnic'],['notebook','Notebook']].map(([v,n])=>`<button data-nav="${v}" class="${active===v?'active':''}" ${active===v?'aria-current="page"':''}>${n}</button>`).join('')}</nav><button class="help" data-nav="tutorial" aria-label="Open tutorial">?</button></header><div class="body"><aside class="sidebar"><section class="specimen"><span class="wave-stamp">Your field specimen</span><div class="fly-picture">${fly}</div><strong>Fly ${String(st.runs.length+1).padStart(2,'0')}</strong><small>${st.live?'Experiment in progress':'Ready for the picnic'}</small><p class="notice">${st.runs.length} recorded ${st.runs.length===1?'attempt':'attempts'}</p></section><section class="brain" aria-label="Brain monitor"><h3>Brain monitor</h3><div class="monitor" id="monitor">${monitor()}</div><small>Schematic layout, not anatomy. Rates are whole-brain model runs.</small></section></aside><main class="content view-${st.view}">${views[st.view]()}</main></div><footer class="footer"><span>${brain.label} · 200 ms reset-state trials · picnic seed ${seed}</span><span>Feeding and escape come from the model. Walking, jumps and the learning rule are authored.</span></footer></div>`;bind();if(st.view==='live')updateLive();}
function policy(group){const g=grp[group],p=st.config.policy[g];return `<div class="setting"><label>${group==='bitter'?'Bitter':'Threat'} learning</label><div class="seg">${['responsive','conservative'].map(x=>`<button data-policy="${group}:${x}" class="${p===x?'active':''}">${x[0].toUpperCase()+x.slice(1)}${POLICY_COST[x]?` · ${POLICY_COST[x]} pt`:''}</button>`).join('')}</div><p class="policy-detail">${p==='responsive'?'Responsive: one qualifying experience changes this connection group by one level. Adapts quickly, including after a misleading encounter.':'Conservative: waits for three qualifying experiences before changing this connection group by one level. Changes more slowly and retains its starting behavior longer.'}</p></div>`}
function meter(){const left=budget()-cost();return {left,html:Array.from({length:budget()},(_,i)=>`<i class="${i<left?'lit':''}"></i>`).join('')}}
const views={workbench(){let m=meta[st.selected],k=st.selected,mt=meter(),slider=['bitter','threat','swarm'].includes(k);return `<div class="loadout-budget"><span>${title(st.level)} · Available points</span><div class="point-meter" role="meter" aria-label="Available upgrade points" aria-valuemin="0" aria-valuemax="${budget()}" aria-valuenow="${mt.left}">${mt.html}</div><strong class="budget">${mt.left} / ${budget()}</strong></div><div class="workbench"><section class="tree" aria-label="Capability branches"><div class="branch"><div class="branch-title">Feeding</div><div class="nodes">${node('sugar')}${node('bitter')}${node('water')}</div></div><div class="branch"><div class="branch-title">Escape</div><div class="nodes">${node('threat')}${node('learn')}${node('swarm')}</div></div><p class="tree-note">Build your loadout!</p></section><section class="inspector"><h3>${m.title}</h3><p>${m.desc}</p>${slider?`<div class="setting"><label for="level">${k==='swarm'?'Swarm size':'Starting level'} <span class="readout">${levelText(st.config,k)}</span></label><input id="level" type="range" min="0" max="${k==='swarm'?SWARM_SIZES.length-1:scales[grp[k]].length-1}" step="1" value="${level(st.config,k)}" aria-label="${m.title}" aria-valuetext="${levelText(st.config,k)}"><div class="range-ends"><span>Lower</span><span>Higher</span></div></div>`:''}${k==='sugar'?`<div class="setting"><label>Sugar input <span class="readout">${st.config.sugarHz} Hz</span></label><div class="seg">${sugars.map(x=>`<button data-sugar="${x}" class="${st.config.sugarHz===x?'active':''}" aria-pressed="${st.config.sugarHz===x}">${x} Hz${SUGAR_COST[x]?` · ${SUGAR_COST[x]} pt`:''}</button>`).join('')}</div><p class="policy-detail">Two input strengths were run in the model, so there are two settings.</p></div>`:''}${k==='bitter'||k==='learn'?policy('bitter'):''}${k==='threat'||k==='learn'?policy('threat'):''}<p class="notice">${m.detail}</p><button data-act="info">Connection details</button></section></div><div class="bottom-actions"><button data-act="reset">Reset settings</button>${st.live?'<button data-act="resume">Resume attempt</button>':''}<span class="notice" id="allocated">${allocated()}</span><button class="primary" data-act="release" ${canRelease()?'':'disabled'}>Release Fly</button></div>`},picnic(){return `<div class="garden"><div class="arrival-fly" aria-hidden="true">${fly}</div><div class="garden-title"><h2>One small step for fly. One giant buzz for flykind.</h2><p>Mack's Pest Control is on the way. Can you build a brain that gets you across the picnic before he gets here?</p><div class="seg levels" role="group" aria-label="Level">${LEVELS.map((l,n)=>`<button data-level="${l}" class="${st.level===l?'active':''}" aria-pressed="${st.level===l}" ${st.live?'disabled':''}>Level ${n+1}${beaten(l)?' ✓':''}</button>`).join('')}</div><p class="notice"><b>${title(st.level)}.</b> Get two flies across and laying eggs. Watch for: ${lvl().obstacles.join('; ')}.</p><div class="arrival-actions"><button class="primary" data-nav="workbench">Build your fly</button><button data-act="scout" ${st.live?'disabled':''}>Scout: basic model</button></div><button class="quiet" data-nav="tutorial">First time here?</button></div><button class="notebook-hotspot" data-act="open-book"><span>Open notebook</span><small>${st.runs.length} recorded attempts</small></button></div><div class="bottom-actions">${st.live?'<button data-act="resume">Resume encounter</button><button data-act="finish">End attempt</button>':''}</div>`},live(){const s=st.live;if(!s)return empty();const fr=s.wave.fruit;return `<div class="screen-head"><div><h2>${title(s.wave.id)}</h2><p id="phase"></p></div><div class="toolbar"><button data-act="pause" id="pause">${st.paused?'Play':'Pause'}</button>${[.5,1,2,4].map(v=>`<button data-speed="${v}" class="${st.speed===v?'active':''}">${v}×</button>`).join('')}</div></div><div class="live-stats"><span>Swarm energy <b id="energy"></b><div class="bar"><i id="energy-bar"></i></div></span><span>Water <b id="water"></b><div class="bar"><i id="water-bar"></i></div></span><span>Alive <b id="alive"></b></span><span>Across and laying <b id="across"></b></span><span>Eggs <b id="eggs"></b></span><span id="clock"></span></div><div class="arena world" id="arena"><div class="ent fruit-zone" style="left:${fr.x/ARENA.w*100}%;top:${fr.y/ARENA.h*100}%;width:${fr.r*2/ARENA.w*100}%;height:${fr.r*2/ARENA.h*100}%" title="Fruit: the far side of the picnic">Fruit</div>${(s.wave.candles??[]).map(c=>`<div class="ent haze" style="${px(c.x,c.y)};width:${90/ARENA.w*100}%;height:${90/ARENA.h*100}%"></div><div class="ent candle" style="${px(c.x,c.y)}" title="Citronella candle: food in its haze tastes bitter"></div>`).join('')}<div id="ents"></div><div id="flies"></div><div class="arena-label" id="action"></div></div><div class="event-line" id="event" aria-live="polite"></div><div class="event-line legend notice">S sugar food · B bitter-tasting food (citronella-coated or poisoned: the fly tastes the same thing) · W water · So soda · yellow haze = citronella candle · dashed grey = passing shadow · red = swat · pale = Mack’s fog</div><div class="bottom-actions"><span id="levels" class="notice"></span><button data-act="finish">End & review</button></div>`},results(){let a=chosen();if(!a)return empty();let r=a.record,ev=decisiveEvents(r),learned=r.events.filter(e=>e.learning?.applied);return `<div class="screen-head"><div><h2>${r.result==='survived'?'A picnic survived.':'A useful experiment.'}</h2><p>Attempt ${number(a)} · ${title(r.wave)} · ${outcome(r)} · ${mode(r)}</p></div><button data-nav="notebook">Save & open notebook</button></div><div class="results-grid"><section><h3>Field results</h3>${scoreHtml(r)}${stats(r)}</section><section><h3>What changed?</h3><p class="notice">Started: ${brainLine(r.config)}.<br>Ended: bitter ×${r.finalState.bitterScale}, threat ×${r.finalState.loomGfScale}.</p><ul class="events">${learned.map(e=>`<li>${learnText(e)}</li>`).join('')||'<li>No weight changed in this attempt.</li>'}</ul><p class="notice">Authored learning applied to real connectivity. Each level’s effect is the measured model response.</p></section></div><div class="replay"><h3>Replay the evidence <button class="replay-play" data-act="replay-play" ${ev.length?'':'disabled'} aria-label="Play through each brain change">▶ Play brain changes</button></h3>${ev.length?`<input id="replay" aria-label="Decisive events" type="range" min="0" max="${ev.length-1}" value="${Math.min(st.replay,ev.length-1)}"><div id="replay-detail"></div>`:'<p class="notice">No weight updates, damage or escapes were recorded in this attempt.</p>'}</div><div class="bottom-actions"><button data-act="restore">Revise starting brain</button><button data-act="compare">Compare Frozen Learning</button>${r.result==='survived'?`<button class="primary" data-act="advance">${LEVELS.indexOf(r.wave)<LEVELS.length-1?'Next level':'Final summary'}</button>`:'<button class="primary" data-act="retry">Retry this level</button>'}</div>`},notebook(){let a=chosen(),r=a?.record;return `<div class="screen-head"><div><h2>Field Notebook</h2></div><div class="toolbar"><button data-act="export" ${!st.runs.length?'disabled':''}>Export records</button></div></div>${!a?`<div class="empty"><h3>A fresh page.</h3><p>Release your first fly to record its settings, discoveries, and results.</p><button class="primary" data-nav="workbench">Open workbench</button></div>`:`<div class="book"><section class="book-page"><h3>Recorded attempts</h3>${[...st.runs].reverse().map(x=>`<button class="run-entry ${x.id===a.id?'active':''}" data-run="${x.id}"><strong>Attempt ${number(x)} · ${title(x.record.wave)}</strong><span>${x.record.result==='survived'?'Cleared':pct(x.record.metrics.progress)+' across'} · ${score(x.record,defaults).total} points · ${x.record.metrics.flies} flies</span></button>`).join('')}</section><section class="book-page"><h3>Attempt ${number(a)} · ${score(r,defaults).total} points</h3>${stats(r)}<p class="notice">Starting brain: ${brainLine(r.config)}.<br>Learning: bitter ${r.config.policy.bitter}, threat ${r.config.policy.loomGf}.<br>Final brain: bitter ×${r.finalState.bitterScale}, threat ×${r.finalState.loomGfScale}.</p><ul class="events">${r.events.filter(e=>e.learning?.applied).map(e=>`<li>${learnText(e)}</li>`).join('')||'<li>No weight changed.</li>'}</ul><p class="notice">Picnic seed ${r.worldSeed} · ${r.version.core} · controller ${r.version.controller} · rule ${r.version.learningRule} · brain export ${r.version.brainExportedAt??'unknown'} · ${r.decisions.length} lookups and ${r.events.length} events in the exported log.</p><div class="bottom-actions"><button data-act="restore">Restore start</button><button data-act="restore-final">Use adapted brain</button><button data-act="review">Replay</button></div></section></div>`}`},compare(){let c=st.compare;if(!c)return empty();const d=c.div;return `<div class="screen-head"><div><h2>Did learning help?</h2><p>Same starting brain, picnic seed and body controller. One difference. ${verdict(c)}</p></div><button data-nav="results">Back to replay</button></div><div class="compare">${[c.adaptive,c.frozen].map((r,i)=>`<section><h3>${i?'Frozen connections':'Adaptive connections'}</h3><p>${i?'Starting weights stay fixed.':'Experience can change the weights.'}</p>${stats(r)}<p>Final bitter: <b>×${r.finalState.bitterScale}</b><br>Final threat: <b>×${r.finalState.loomGfScale}</b></p><ul class="events">${r.events.filter(e=>e.learning?.applied).map(e=>`<li>${learnText(e)}</li>`).join('')||'<li>Weights remained at their starting levels.</li>'}</ul></section>`).join('')}</div><div class="pad"><p class="notice">${d?`The two flies first differ at ${d.t.toFixed(1)} s. Adaptive${at(d.a)}: ${d.a?.reason??'no lookup'}. Frozen${at(d.b)}: ${d.b?.reason??'no lookup'}. After that they can meet different inputs.`:'The two flies made the same decisions throughout.'}</p><p class="notice">Both runs are full encounters looked up from the same measured model export. Learning can help or hurt.</p><button class="primary" data-nav="workbench">Try another configuration</button></div>`},tutorial(){return `<div class="screen-head"><h2>Welcome to BuzzFYL.</h2><button data-nav="workbench">Skip tutorial</button></div><div class="tutorial">${[['Get the swarm across the picnic.','Three levels at the Bennett family picnic, ending with Mack’s Pest Control. To clear a level, at least two flies must reach the fruit alive and lay eggs. Your flies act on their own. You shape the brain they all share, and you are scored on eggs, health, flies lost and points left unspent.'],['Build within your budget.','Select a capability in the workbench. Adjust its starting level and choose how readily it changes through experience. Moving a weight one level costs a point. The brain monitor shows what the model measured for your build.'],['Let the fly discover the picnic.','You do not steer. Watch it encounter food, water and approaching threats. Pause, slow down, or fast-forward. The map stays the same when you retry.'],['Experience changes the next decision.','Safe bitter meals can weaken bitter responses. Poisoning can strengthen them. Harmless shadows can lower threat sensitivity and hits raise it. These are authored learning rules applied to real connection groups.'],['Inspect. Adjust. Try again.','Replay the decisive events. Compare adaptive versus frozen learning, then restore a configuration from your field notebook.'],['What is real here.','Every feed, drink and jump decision is a lookup of a whole-fly-brain model run (FlyWire connectome) at the fly’s current weights. Walking, jump direction, energy, poison and the learning rule are game mechanics. Citronella is a stand-in read through bitter taste cells.']].map(([a,b],i)=>`<section><div class="num">${i+1} / 6</div><h2>${a}</h2><p>${b}</p></section>`).join('')}<button class="primary" data-nav="workbench">Prepare your first fly</button></div>`},summary(){const a=chosen(),r=a?.record;return `<div class="summary"><div class="fly-picture">${fly}</div><h2>You outlasted pest control.</h2><p class="score">Best scores: ${LEVELS.map((l,n)=>`Level ${n+1} <b>${Math.max(0,...st.runs.filter(a=>a.record.wave===l).map(a=>score(a.record,defaults).total))}</b>`).join(' · ')}</p><p>Your field notebook holds the story of how your fly changed.</p>${r?`<p>Began with ${brainLine(r.config)}.<br>Became bitter ×${r.finalState.bitterScale}, threat ×${r.finalState.loomGfScale} after ${r.metrics.adaptations} weight ${r.metrics.adaptations===1?'update':'updates'}.<br>${r.metrics.fliesAcross} of ${r.metrics.flies} flies across, ${r.metrics.eggsLaid} ${r.metrics.eggsLaid===1?'egg':'eggs'} laid, ${r.metrics.damageTaken} damage taken.</p>`:''}<p>${st.runs.length} boss attempts recorded</p><button class="primary" data-nav="notebook">Open the notebook</button> <button data-act="new">Back to the picnic</button><p class="notice">Authored learning applied to real connectivity. Every lookup is a fresh 200 ms trial.</p></div>`}};
const at=d=>d?` (bitter ×${d.state.bitterScale}, threat ×${d.state.loomGfScale})`:'';
function allocated(){return measured(st.config)?`${cost()} points allocated`:'This brain state is not measured yet'}
function mode(r){return r.config.policy.bitter==='frozen'&&r.config.policy.loomGf==='frozen'?'Frozen Learning':'Adaptive Learning'}
function node(k){return `<button class="node ${st.selected===k?'selected':''}" data-node="${k}">${icon(k)}${meta[k].title}${k==='water'?'<small>Measured, weak</small>':''}</button>`}function empty(){return '<div class="empty"><h2>No attempt yet.</h2><button data-nav="workbench">Open workbench</button></div>'}
function stats(r){const m=r.metrics;return `<table class="stats-table">${[['Encounter progress',pct(m.progress)],['Outcome',outcome(r)],['Flies across and laying',`${m.fliesAcross} of ${m.flies} (need 2)`],['Flies alive at the end',`${m.fliesAlive} of ${m.flies}`],['Servings completed',m.servingsCompleted],['Drinks',m.drinks],['Eggs laid (bonus)',m.eggsLaid],['Damage taken',m.damageTaken],['Escape jumps',`${m.jumps} (${m.jumpsOnHarmless} at harmless shadows)`],['Attacks that missed after a jump',m.attacksEscaped],['Meals interrupted by a jump',m.mealsInterruptedByJump],['Weight updates',m.adaptations]].map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</table>`}
function scoreHtml(r){const s=score(r,defaults);return `<p class="score">Score <b>${s.total.toLocaleString()}</b></p><table class="stats-table score-table">${s.parts.map(p=>`<tr><td>${p.label} <small>${p.detail}</small></td><td>${p.points>0?'+':''}${p.points}</td></tr>`).join('')}</table>`}
function learnText(e){const l=e.learning;return `${e.t.toFixed(1)} s · ${e.feedback}: ${glow[l.group]} ×${l.scaleBefore} → ×${l.scaleAfter}`}
function verdict(c){const a=c.adaptive,f=c.frozen,ok=r=>r.result==='survived';if(ok(a)&&!ok(f))return 'Here learning helped.';if(!ok(a)&&ok(f))return 'Here learning hurt.';return `Same outcome either way; score ${score(a,defaults).total} adaptive, ${score(f,defaults).total} frozen.`}

// ---- commands onto the core --------------------------------------------------------------
function release(config){st.notice='';st.live=new Sim(brain,{wave:st.level,seed,config:clone(config),onEvent:e=>{if(e.outcome==='serving_refused'&&!e.learning)return;const l=e.learning;st.notice=`${e.t.toFixed(1)} s · ${e.feedback}${l?` · ${gname[l.group]}: ${l.applied?`×${l.scaleBefore} → ×${l.scaleAfter}`:l.note}`:''}`}});st.paused=false;st.speed=1;acc=0;nav('live')}
function finish(){let s=st.live;if(!s)return;const a=saveAttempt(s.record());st.runs.push(a);st.live=null;st.chosen=a.id;st.replay=0;st.view='results';render()}
const px=(x,y)=>`left:${x/ARENA.w*100}%;top:${y/ARENA.h*100}%`;
const foodLook={clean:['','S','Sugar food'],safe_bitter:['bitter','B','Bitter-tasting food'],poison_bitter:['bitter','B','Bitter-tasting food'],citronella:['bitter','B','Bitter-tasting food beside a citronella candle'],water:['water','W','Water droplet'],soda:['soda','So','Spilled soda: sugar and water']};
function updateLive(){let s=st.live;if(!s||!$('#flies'))return;const m=s.metrics,alive=s.flies.filter(f=>f.alive),avg=k=>alive.length?alive.reduce((a,f)=>a+f[k],0)/alive.length:0,lead=s.fly;$('#energy').textContent=Math.round(avg('energy'));$('#energy-bar').style.width=avg('energy')/GAME.maxEnergy*100+'%';$('#water').textContent=Math.round(avg('hydration'));$('#water-bar').style.width=avg('hydration')/GAME.maxHydration*100+'%';$('#alive').textContent=m.fliesAlive+'/'+m.flies;$('#across').textContent=m.fliesAcross+' (need '+s.wave.fliesNeeded+')';$('#eggs').textContent=m.eggsLaid;$('#clock').textContent=Math.floor(s.t)+' / '+s.wave.duration+' s';$('#phase').textContent=`${s.phase} · ${mode(s)}`;$('#action').textContent='Lead fly: '+actions[lead.action];$('#event').textContent=st.notice||'The swarm is exploring. No adaptation recorded yet.';
  $('#levels').textContent=['bitter','loomGf'].map(g=>{const x=s.groups[g],e=x.evidence;return `${g==='bitter'?'Bitter':'Threat'} ×${scales[g][x.startLevel]} → ×${scales[g][x.level]}${e.direction?` (pending ${e.count}/${x.threshold} to ${e.direction})`:''}`}).join(' · ');
  $('#flies').innerHTML=s.flies.map(f=>`<div class="fly-token ent ${f.action} ${f.alive?'':'dead'} ${s.flies.length>4?'small':''}" style="${px(f.x,f.y)};transform:translate(-50%,-50%) rotate(${f.heading*180/Math.PI+90}deg)" title="Fly ${f.id+1}: health ${Math.round(f.health)}">${fly}</div>`).join('');
  $('#ents').innerHTML=s.servings.filter(x=>x.status==='available').map(x=>{const[c,t,title]=foodLook[x.kind];return `<div class="ent food ${c} ${x.refusedUntil>s.t?'dim':''}" style="${px(x.x,x.y)}" title="${title}">${t}${x.progress>0?`<u style="width:${x.progress*100}%"></u>`:''}</div>`}).join('')+s.threats.filter(t=>t.status==='active').map(t=>`<div class="ent threat show ${t.kind}" style="${px(t.x,t.y)};width:${CTRL.hitRadius*2/ARENA.w*100}%;height:${CTRL.hitRadius*2/ARENA.h*100}%"><span>${t.kind==='fog'?'Mack’s fog':t.kind==='swat'?'Swat':'Shadow'}</span></div>`).join('');
  if(s.lastDecision?.id!==shown){shown=s.lastDecision?.id;updateMonitor()}}
let shown=null;
function replayDetail(){let a=chosen(),box=$('#replay-detail');if(!a||!box)return;const r=a.record,ev=decisiveEvents(r),e=ev[Math.min(st.replay,ev.length-1)];if(!e)return;const{decision:d}=replay(r,e),l=e.learning;box.innerHTML=`${d?`<div class="replay-map">${brainMap(d,d.state,null)}</div>`:''}<p><b>Event ${Math.min(st.replay,ev.length-1)+1} of ${ev.length} · ${e.t.toFixed(1)} s · ${e.outcome.replaceAll('_',' ')}${e.flyId!=null?` · fly ${e.flyId+1}`:''}</b></p><ol class="events">${d?`<li>Sensory input: sugar ${d.stimulus.sugar} Hz, bitter ${d.stimulus.bitter} Hz, looming ${d.stimulus.looming} Hz${d.stimulus.water?`, water ${d.stimulus.water} Hz`:''}. Condition ${d.conditionId}, model seed ${d.replicateSeed}.</li><li>Measured output: MN9 ${hz(d.readouts.mn9)}, Giant Fibre ${hz(d.readouts.giant_fibre)}, MDN ${hz(d.readouts.mdn)}.</li><li>Controller action: ${d.action}. ${d.reason}.</li>`:'<li>No lookup is linked to this event.</li>'}<li>Resolved feedback: ${e.feedback}.</li><li>Weight update: ${l?`${glow[l.group]}, evidence ${l.evidenceBefore.count} → ${l.note}. ${l.applied?`Weight ×${l.scaleBefore} → ×${l.scaleAfter}; the next decision uses it.`:`Weight stays ×${l.scaleBefore}.`}`:'none. This event gives no evidence.'}</li></ol>`}
// Steps through the stored weight-update events (all decisive events if no weight changed). Recorded data only.
let replayTimer=null;
function stopReplay(){if(replayTimer){clearInterval(replayTimer);replayTimer=null}const b=document.querySelector('.replay-play');if(b)b.textContent='▶ Play brain changes'}
function playReplay(){if(replayTimer)return stopReplay();const a=chosen();if(!a)return;const ev=decisiveEvents(a.record);let steps=ev.map((e,i)=>e.learning?.applied?i:-1).filter(i=>i>=0);if(!steps.length)steps=ev.map((_,i)=>i);if(!steps.length)return;let n=0;const show=()=>{st.replay=steps[n];const r=$('#replay');if(r)r.value=st.replay;replayDetail()};show();$('.replay-play').textContent='❚❚ Pause';replayTimer=setInterval(()=>{n++;if(n>=steps.length||!$('#replay-detail'))return stopReplay();show()},1600)}
function bind(){document.querySelectorAll('[data-nav]').forEach(e=>e.onclick=()=>nav(e.dataset.nav));document.querySelectorAll('[data-node]').forEach(e=>e.onclick=()=>{st.selected=e.dataset.node;render()});$('#level')?.addEventListener('input',e=>{setLevel(st.config,st.selected,+e.target.value);const t=levelText(st.config,st.selected),mt=meter();$('.readout').textContent=t;e.target.setAttribute('aria-valuetext',t);$('.budget').textContent=mt.left+' / '+budget();$('.point-meter').setAttribute('aria-valuenow',mt.left);document.querySelectorAll('.point-meter i').forEach((segment,i)=>segment.classList.toggle('lit',i<mt.left));document.querySelector('[data-act=release]').disabled=!canRelease();$('#allocated').textContent=allocated();updateMonitor()});document.querySelectorAll('[data-policy]').forEach(e=>e.onclick=()=>{let[g,p]=e.dataset.policy.split(':');st.config.policy[grp[g]]=p;render()});document.querySelectorAll('[data-sugar]').forEach(e=>e.onclick=()=>{st.config.sugarHz=+e.dataset.sugar;render()});document.querySelectorAll('[data-level]').forEach(e=>e.onclick=()=>{if(st.live)return;st.level=e.dataset.level;render()});document.querySelectorAll('[data-speed]').forEach(e=>e.onclick=()=>{st.speed=+e.dataset.speed;render()});document.querySelectorAll('[data-run]').forEach(e=>e.onclick=()=>{st.chosen=e.dataset.run;render()});$('#replay')?.addEventListener('input',e=>{stopReplay();st.replay=+e.target.value;replayDetail()});document.querySelectorAll('[data-act]').forEach(e=>e.onclick=()=>act(e.dataset.act));replayDetail()}
function act(a){let r=chosen();if(a==='scout'){if(st.live)return;release(scout)}if(a==='release'){if(!canRelease())return;release(st.config)}if(a==='pause'){st.paused=!st.paused;render()}if(a==='resume'){st.paused=false;nav('live')}if(a==='finish')finish();if(a==='reset'){st.config=clone(defaults);render()}if(a==='info')toast(meta[st.selected].group+'. FlyWire v783 neuron IDs are in the export; measured rates are on the brain monitor.');if(a==='restore'||a==='restore-final'){if(!r)return;if(!st.live)st.level=r.record.wave;st.config=restoreBuild(r,a==='restore'?'start':'final');nav('workbench');toast(a==='restore'?'Starting configuration restored.':cost()>budget()?'Adapted configuration restored. It is over budget: adjust before release.':'Adapted configuration restored.')}if(a==='review'){st.replay=0;nav('results')}if(a==='replay-play')playReplay();if(a==='retry'){if(!r||st.live)return;st.level=r.record.wave;st.config=restoreBuild(r,'start');release(st.config)}if(a==='advance'){const n=LEVELS.indexOf(r.record.wave);if(n<LEVELS.length-1){st.level=LEVELS[n+1];nav('picnic')}else nav('summary')}if(a==='compare'){if(!r)return;const cfg=r.record.config,[adaptive,frozen]=runPair(brain,r.record.wave,r.record.worldSeed,cfg,frozenTwin(cfg));st.compare={adaptive,frozen,div:firstDivergence(adaptive,frozen)};nav('compare')}if(a==='export'){let b=new Blob([JSON.stringify(st.runs,null,2)],{type:'application/json'}),u=URL.createObjectURL(b),l=document.createElement('a');l.href=u;l.download='buzzfyl-notebook.json';l.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}if(a==='new'){nav('picnic')}if(a==='open-book'){st.bookReturn='picnic';nav('notebook')}}
// The UI owns the clock. Speed and pause change how fast fixed core steps are consumed, never the result.
let acc=0,prev=performance.now();
function frame(now){const dt=Math.min(.1,(now-prev)/1000);prev=now;if(st.view==='live'&&st.live&&!st.paused){acc+=dt*st.speed;const n=Math.floor(acc/CTRL.dt);if(n>0){acc-=n*CTRL.dt;st.live.step(n*CTRL.dt);updateLive();if(st.live.done)finish()}}requestAnimationFrame(frame)}
// Dev aid: ?view=workbench|notebook|tutorial|live|results|compare (&t=seconds for live) opens a screen directly.
{const v=query.get('view');if(v==='live'||v==='results'||v==='compare'){release(st.config);st.live.step(v==='live'?Number(query.get('t')??20):999);if(v==='live')st.paused=true;else{finish();if(v==='compare')act('compare')}}else if(views[v])st.view=v}
render();requestAnimationFrame(frame);

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&st.view==='notebook'){nav(st.bookReturn||'picnic')}else if(e.key==='Escape'&&st.view==='live'){st.paused=!st.paused;render()}});
